// Источник: web-тест .qa/e2e/tests/journey/jr-04-commitment-set-remove-restore.spec.ts, план .qa/e2e/specs/journey.md (14.6), кейс .qa/tests/journey/JR-04-personal-kabbala.md
// Тикеты #6a86f7fb, #31c88137. Опора: «קבלה אישית» AC1–AC4; #31c88137 «מה רצוי» (поле раскрывается уже с сохранённой קבלה; до конца загрузки редактирование недоступно).
// @data: меняет קבלה user1; в finally возвращается исходное «test». «reload» web = перезапуск приложения (terminate/activate).
import { $, driver, expect } from '@wdio/globals';
import { byText, byTextContains, byLabelStartsWith, tapText, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const ORIGINAL = 'test';
const NEW_VALUE = 'QA-AUTO-קבלה';
const LOADING = 'טוענים את הקבלה האישית…';
const PLACEHOLDER = 'מה אני מקבל על עצמי';

const appId = () => (driver.isAndroid ? process.env.APP_ANDROID_PACKAGE : process.env.APP_IOS_BUNDLE) ?? '';
async function relaunch() {
  await driver.terminateApp(appId());
  await driver.activateApp(appId());
  await (await byText('בית')).waitForDisplayed({ timeout: 30000 });
}
function field() {
  return driver.isAndroid
    ? $('android=new UiSelector().className("android.widget.EditText")')
    : $('-ios class chain:**/XCUIElementTypeTextView');
}
/** Значение поля без подсказки (на Android пустой EditText может отдавать hint как text). */
async function fieldValue(): Promise<string> {
  const f = await field();
  const text = driver.isAndroid ? await f.getText() : ((await f.getAttribute('value')) ?? '');
  const hint = driver.isAndroid ? await f.getAttribute('hint').catch(() => '') : await f.getAttribute('placeholderValue').catch(() => '');
  return text === hint || text === PLACEHOLDER ? '' : text;
}
/** «המסע שלי» → дождаться конца загрузки קבלה (строка загрузки исчезла). */
async function openJourney() {
  await goTab('המסע שלי');
  await (await byText('המסע שלי')).waitForDisplayed({ timeout: 20000 });
  const w = await byTextContains('עלית דרגה');
  if (await w.waitForDisplayed({ timeout: 1500 }).then(() => true, () => false)) await tapText('סגירה');
  await scrollToText('מקבל על עצמי');
  await (await byText(LOADING)).waitForDisplayed({ reverse: true, timeout: 30000 });
}
async function openCommitment() {
  await (await byLabelStartsWith('מקבל על עצמי')).click();
  const f = await field();
  await f.waitForDisplayed();
  await expect(f).toBeEnabled();
  return f;
}
/** «שמירה» и дождаться, пока окно правки закроется (запись ушла). */
async function save() {
  await tapText('שמירה');
  await (await byText('שמירה')).waitForDisplayed({ reverse: true, timeout: 20000 });
}

describe('«המסע שלי»', () => {
  afterEach(async () => { await toHome(); });

  it('JR-04 «מקבל על עצמי» — задать, удалить, вернуть; без фиктивного прогресса #6a86f7fb #31c88137 @data', async () => {
    try {
      // 1. Раскрыть: поле уже с «test» и доступно; лимит 280 знаков; ввести «QA-AUTO-קבלה» → «שמירה»; перезапуск.
      await openJourney();
      let f = await openCommitment();
      expect(await fieldValue()).toBe(ORIGINAL);
      await f.setValue('א'.repeat(281));                  // maxlength=280 (в web — атрибут; здесь — по факту ввода)
      expect((await fieldValue()).length).toBe(280);
      await f.setValue(NEW_VALUE);
      await save();
      await relaunch();
      await openJourney();
      await expect(byTextContains(NEW_VALUE)).toBeDisplayed();
      await expect(byTextContains('%')).not.toBeDisplayed();   // рядом нет процентов/фиктивного прогресса

      // 2. «הסרת הקבלה» только очищает поле (без окна) → «שמירה»; перезапуск → пустое состояние.
      f = await openCommitment();
      await tapText('הסרת הקבלה');
      await expect(byText('ביטול')).not.toBeDisplayed();       // окна подтверждения нет
      expect(await fieldValue()).toBe('');
      await save();
      await relaunch();
      await openJourney();
      await expectVisibleText('עדיין לא הגדרת קבלה אישית.');
    } finally {
      // 3. Уборка: вернуть «test».
      await toHome();
      await openJourney();
      if (!(await (await byTextContains(ORIGINAL)).isDisplayed().catch(() => false))) {
        const f = await openCommitment();
        await f.setValue(ORIGINAL);
        await save();
        await relaunch();
        await openJourney();
      }
      await expect(byTextContains(ORIGINAL)).toBeDisplayed();
    }
  });
});
